a2a:agent-card.a2a:json:
{
  "name": "${aena.agente.nombre}",
  "description": "Agente de AENA para aerolíneas: busca vuelos, reserva parking en los aeropuertos de AENA y gestiona pagos con la pasarela. Razona con un LLM y ejecuta las tools de sus servidores MCP (vuelos, parking y pagos).",
  "version": "${aena.agente.version}",
  "protocolVersion": "1.0",
  "provider": { "organization": "${aena.agente.organizacion}", "url": "https://www.aena.es" },
  "supportedInterfaces": [
    { "protocolBinding": "JSONRPC",   "url": "${poc.urlPublica}${poc.rutas.aena.agente}/rpc", "protocolVersion": "1.0", "tenant": "" },
    { "protocolBinding": "HTTP+JSON", "url": "${poc.urlPublica}${poc.rutas.aena.agente}",     "protocolVersion": "1.0", "tenant": "" }
  ],
  "capabilities": { "streaming": false, "pushNotifications": false, "extendedAgentCard": false },
  "securitySchemes": {
    "apiKey": { "apiKeySecurityScheme": { "location": "header", "name": "X-API-Key", "description": "API key de la POC (cabecera X-API-Key)" } }
  },
  "securityRequirements": [ { "schemes": { "apiKey": { "list": [] } } } ],
  "skills": [
    {
      "id": "servicios-aeroportuarios",
      "name": "Vuelos, parking y pagos AENA",
      "description": "Entrada recomendada: DataPart JSON {accion, argumentos}. Acciones: buscar_vuelos {origen, destino, fecha, pasajeros}, consultar_vuelo {vueloId, pasajeros}, buscar_parking {aeropuerto, fechaEntrada, fechaSalida}, reservar_parking {aeropuerto, opcionId, fechaEntrada, fechaSalida, matricula, referencia}, crear_pago {referencia, importe, concepto}, estado_pago {idPago}. También acepta texto libre. Salida: artifact 'resultado-aena' con un JSON {tipo, ...}.",
      "tags": ["aena", "vuelos", "parking", "pagos", "aeropuerto"],
      "examples": [
        "Busca vuelos de Madrid a Londres el 2026-11-20 para 2 pasajeros",
        "¿Qué parking hay en Barajas del 20 al 27 de noviembre?"
      ],
      "inputModes": ["application/json", "text/plain"],
      "outputModes": ["application/json", "text/plain"]
    }
  ],
  "defaultInputModes": ["application/json", "text/plain"],
  "defaultOutputModes": ["application/json", "text/plain"]
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json skipNullOn="everywhere"
var r = vars.resultado
var resumen = if (r.tipo == "error") ("AENA no ha podido completar la acción: " ++ ((r.mensaje default r.codigo default "error") as String))
              else ("AENA ha completado la acción " ++ (if (vars.accion == "") "solicitada" else vars.accion) ++ " (resultado de tipo " ++ (r.tipo as String) ++ ").")
---
{
    status: {
        state: "TASK_STATE_COMPLETED",
        message: {role: "ROLE_AGENT", messageId: uuid(), parts: [{text: resumen}]}
    },
    artifact: {
        artifactId: uuid(),
        name: "resultado-aena",
        description: "Resultado de la acción solicitada a AENA",
        parts: [
            {data: r, mediaType: "application/json"},
            {text: resumen}
        ]
    },
    metadata: {
        correlationId: vars.correlationId,
        accion: vars.accion,
        origenCalculo: vars.origenCalculo,
        modeloLlm: if (p('aena.agente.usarLlm') == 'true') p('poc.llm.modelo') else null
    }
}

a2a:update-task-status.a2a:status-content:
#[%dw 2.0
output application/json
---
{
    statusUpdate: {
        taskId: vars.a2aCtx.taskId,
        contextId: vars.a2aCtx.contextId,
        status: {
            state: "TASK_STATE_REJECTED",
            message: {
                role: "ROLE_AGENT",
                messageId: uuid(),
                parts: [{ text: error.description default "No autorizado" }]
            }
        }
    }
}]

#[%dw 2.0
output application/json
---
{
    statusUpdate: {
        taskId: vars.a2aCtx.taskId,
        contextId: vars.a2aCtx.contextId,
        status: {
            state: "TASK_STATE_FAILED",
            message: {
                role: "ROLE_AGENT",
                messageId: uuid(),
                parts: [{ text: "AENA no ha podido atender la solicitud: " ++ (error.description default "error desconocido") ++ " (correlationId: " ++ (vars.correlationId default "") ++ ")" }]
            }
        }
    }
}]
